crypto_attrs := {"algorithm", "cipher", "encryption_type", "hash_algorithm", "key_length", "key_size", "block_size", "iv_length", "mode", "protocol", "ssl_policy", "tls_version", "kdf", "hash_function", "pbkdf2_iterations", "encoding", "obfuscate", "base64", "custom_algorithm", "proprietary_crypto", "internal_encryption", "legacy_mode", "compatibility_mode", "allow_weak_crypto"}

weak_algorithm_pattern := "(?i).*\\b(DES|3DES|RC4|MD5|SHA1|AES-ECB|AES-128|RSA-1024|blowfish|SHA-1|SHA-1-96|HMAC-SHA1)\\b.*"

weak_key_lengths := {1024, 128, 64, 96}

weak_mode_pattern := "(?i).*\\b(ECB|SSLv2|SSLv3|TLS1\\.0|TLS1\\.1|http)\\b.*"

check_weak_crypto(attr) {
    attr.ir_type == "Attribute"
    crypto_attrs[attr.name]
    attr.value.ir_type == "String"
    regex.match(weak_algorithm_pattern, attr.value.value)
} else {
    attr.ir_type == "Attribute"
    crypto_attrs[attr.name]
    attr.value.ir_type == "Integer"
    weak_key_lengths[attr.value.value]
} else {
    attr.ir_type == "Attribute"
    crypto_attrs[attr.name]
    attr.value.ir_type == "String"
    regex.match(weak_mode_pattern, attr.value.value)
}

